function chunkCurateMemories(memories, maxCharacters) {
  const chunks = [];
  let current = [];
  let size = 0;
  for (const memory of memories) {
    const length = renderMemoryList([memory]).length + 2;
    if (current.length && size + length > maxCharacters) {
      chunks.push(current);
      current = [];
      size = 0;
    }
    current.push(memory);
    size += length;
  }
  if (current.length)
    chunks.push(current);
  const keys = new Map;
  chunks.forEach((chunk, index) => {
    chunk.forEach((memory) => {
      const key = memory.content.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();
      keys.set(key, [...keys.get(key) ?? [], { id: memory.id, chunk: index }]);
    });
  });
  return chunks.map((chunk, index) => ({
    memories: chunk,
    crossChunkCandidates: [...keys.values()].filter((matches) => matches.some((match) => match.chunk === index) && matches.some((match) => match.chunk !== index)).map((matches) => `IDs ${matches.map((match) => match.id).join(", ")}`)
  }));
}
