    const current = db.prepare(`SELECT harness, status, holder_id, started_at, lease_expires_at, completed_at
                 FROM session_project_backfill_state
                 WHERE harness = ?`).get(harness);
    if (current?.status === "completed")
      return "already_completed";
    if (current?.status === "running" && current.lease_expires_at !== null && current.lease_expires_at > now) {
      return "blocked_by_lease";
    }
    db.prepare(`INSERT INTO session_project_backfill_state(
                harness,
                status,
                holder_id,
                started_at,
                lease_expires_at,
                completed_at
            )
             VALUES (?, 'running', ?, ?, ?, NULL)
             ON CONFLICT(harness) DO UPDATE SET
                status = 'running',
                holder_id = excluded.holder_id,
                started_at = excluded.started_at,
                lease_expires_at = excluded.lease_expires_at,
                completed_at = NULL`).run(harness, holderId, now, now + LEASE_TTL_MS);
