var USER_MEMORIES_CHILD_TITLE = "magic-context-dream-user-memories";
var CURATE_CHILD_TITLE = "magic-context-dream-curate";
var MAINTAIN_DOCS_CHILD_TITLE = "magic-context-dream-maintain-docs";
var REFRESH_PRIMERS_CHILD_TITLE = "magic-context-dream-refresh-primers";
var MAP_MEMORIES_CHILD_TITLE = "magic-context-dream-map-memories";
var VERIFY_CHILD_TITLE = "magic-context-dream-verify";
var CLASSIFY_CHILD_TITLE = "magic-context-dream-classify";
var COMPRESS_CUES_CHILD_TITLE = "magic-context-dream-compress-cues";
var MEMORY_MIGRATION_CHILD_TITLE = "magic-context-memory-migration";
