// src/features/magic-context/dreamer/verify-state.ts
import { createHash as createHash6 } from "node:crypto";
import { readFile, realpath as realpath2 } from "node:fs/promises";
import path4 from "node:path";
function verificationMetadata(memory) {
  try {
    const parsed = JSON.parse(memory.metadataJson ?? "{}");
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed))
      return parsed;
  } catch {}
  return {};
}
async function verificationFilesFingerprint(directory, files) {
  const root = await resolveGitTopLevel(directory) ?? path4.resolve(directory);
  const hash = createHash6("sha256");
  for (const file of [...new Set(files)].sort()) {
    const absolute = path4.resolve(root, file);
    const withinRoot = (candidate) => {
      const relative = path4.relative(root, candidate);
      return relative !== ".." && !relative.startsWith(`..${path4.sep}`) && !path4.isAbsolute(relative);
    };
    if (!withinRoot(absolute))
      return null;
    hash.update(JSON.stringify(file));
    try {
      if (!withinRoot(await realpath2(absolute)))
        return null;
      hash.update(createHash6("sha256").update(await readFile(absolute)).digest("hex"));
    } catch (error) {
      if (error.code !== "ENOENT")
        return null;
      hash.update("missing");
    }
  }
  return hash.digest("hex");
}
