// src/features/magic-context/dreamer/manual-summary.ts
function summarizeManualDream(summary) {
  const lines = ["## /ctx-dream", ""];
  if (summary.ran.length > 0)
    lines.push(`Ran: ${summary.ran.join(", ")}`);
  if ((summary.details?.length ?? 0) > 0) {
    lines.push("Details:", ...(summary.details ?? []).map((detail) => `- ${detail}`));
  }
  if (summary.failed.length > 0)
    lines.push(`Failed: ${summary.failed.join(", ")}`);
  if ((summary.failureDetails?.length ?? 0) > 0) {
    lines.push("Failure details:", ...(summary.failureDetails ?? []).map((detail) => `- ${detail}`));
  }
  if (summary.skippedNoWork.length > 0)
    lines.push(`Skipped (no work): ${summary.skippedNoWork.join(", ")}`);
  if (summary.skipped?.length)
    lines.push(`Skipped: ${summary.skipped.join("; ")}`);
  if (summary.deferredBusy.length > 0)
    lines.push(`Busy: ${summary.deferredBusy.join(", ")} — another dream task holds this domain's lease; retry in a minute`);
  if (Object.keys(summary.backlogBefore ?? {}).length > 0) {
    lines.push("", "Backlog at run start:", formatDreamTaskBacklogs(summary.backlogBefore ?? {}));
  }
  if (Object.keys(summary.backlogAfter ?? {}).length > 0) {
    const backlogAfter = { ...summary.backlogBefore ?? {}, ...summary.backlogAfter ?? {} };
    lines.push("", "Backlog at run end:", formatDreamTaskBacklogs(backlogAfter));
  }
  if (summary.ran.length === 0 && summary.failed.length === 0 && summary.skippedNoWork.length === 0 && !summary.skipped?.length && summary.deferredBusy.length === 0) {
    lines.push("No enabled dream tasks to run.");
  }
  return lines.join(`
`);
}

