// src/hooks/magic-context/module-client.ts
function createSubcModuleClient(options) {
  const transport = new SubcModuleTransport(options.connectionFile ?? getDefaultSubcConnectionFile());
  return {
    call: (args) => transport.call(args),
    stateSyncCapabilities: (args) => transport.stateSyncCapabilities(args),
    deleteSession: (sessionId, projectRoot) => transport.deleteSession(sessionId, projectRoot),
    closeSession: (sessionId) => transport.closeSession(sessionId)
  };
}

// src/hooks/magic-context/module-tool-backends.ts
function createModuleToolBackends(options) {
  const { moduleClient } = options;
  if (!moduleClient)
    return;
  return {
    backends: {
      reduce: ({ sessionId, projectRoot, drop, commandId }) => moduleClient.call({
        sessionId,
        projectRoot,
        method: "agent_drops.append",
        body: {
          method: "agent_drops.append",
          v: 1,
          session_id: sessionId,
          drop,
          command_id: commandId
        }
      })
    }
  };
}

